  const chain = frame(parent, { name: "Current release progress", width: "fill_container", height: 46, layout: "horizontal", gap: 0, alignItems: "center", cornerRadius: 7, clipContent: true, fill: F(T.bg), stroke: S(T.lineStrong) });
